<div class="v2-overlay" x-cloak x-show="modal" @click.self="if(modal !== 'ad' || adCountdown <= 0) modal=null">
    <section class="v2-dialog" role="dialog" aria-modal="true" aria-labelledby="modal-title">
        <button class="v2-close" @click="modal=null" aria-label="Close" x-show="modal !== 'ad' || adCountdown <= 0">&times;</button>
        <h2 id="modal-title" x-text="({language:'Choose your language',explain:'Explanation',word:'AI Word',ad:'Sponsored'})[modal]"></h2>
        <template x-if="modal === 'language'"><div><button class="v2-language" @click="setLanguage('en')">English</button><template x-for="item in languages.filter(l=>l.code !== 'en')" :key="item.code"><button class="v2-language" @click="setLanguage(item.code)" x-text="item.name"></button></template></div></template>
        <template x-if="modal === 'explain'"><div><p x-text="current?.explanation_en || 'No explanation is available for this question.'"></p><p class="ku" :dir="direction" x-show="language !== 'en'" x-text="translated(current,'explanation')"></p></div></template>
        <template x-if="modal === 'word'"><div><p>Choose a word from this question to get help with its meaning.</p><label class="v2-field"><span>Word or phrase</span><input x-model="word" type="search" placeholder="Enter a word" maxlength="80" @keydown.enter.prevent="explainWord()"></label><button class="v2-button" @click="explainWord()" :disabled="wordLoading || !word.trim()" x-text="wordLoading ? 'Explaining…' : 'Explain word'"></button><p class="my-4" role="status" x-text="wordError || definition"></p><p style="white-space:pre-line" x-text="wordContext"></p></div></template>
        <template x-if="modal === 'ad' && ad"><div><template x-if="ad.media_type === 'video' && !youtube(ad.media_source)"><video class="v2-ad-media" :src="ad.media_source" controls autoplay playsinline></video></template><template x-if="ad.media_type === 'video' && youtube(ad.media_source)"><iframe class="v2-ad-media" :src="youtube(ad.media_source)+'?autoplay=1&mute=0'" title="Advertisement video" allow="autoplay; fullscreen"></iframe></template><template x-if="ad.media_type !== 'video'"><img class="v2-ad-media" :src="ad.media_source" :alt="ad.title"></template><a class="v2-link" :href="ad.link_url" target="_blank" rel="noopener sponsored">Visit advertiser</a><button class="v2-button" :disabled="adCountdown > 0" @click="modal=null; next()" x-text="adCountdown > 0 ? `Continue in ${adCountdown}s` : 'Continue'"></button></div></template>
    </section>
</div>
